import{_ as e,o,a,a3 as i}from"./chunks/framework.CkbYhqXo.js";const p=JSON.parse('{"title":"Builder","description":"The Stuzhik Builder: put a modpack together without installing it — contents, catalog, compatibility check and dependency graph, configs, .stzhk export and a test run.","frontmatter":{"description":"The Stuzhik Builder: put a modpack together without installing it — contents, catalog, compatibility check and dependency graph, configs, .stzhk export and a test run.","head":[["meta",{"name":"keywords","content":"stuzhik builder, make a minecraft modpack, modpack without installing, mod compatibility check, dependency graph, stzhk export"}]]},"headers":[],"relativePath":"en/guide/builder.md","filePath":"en/guide/builder.md"}'),n={name:"en/guide/builder.md"};function r(s,t,d,h,l,c){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="builder" tabindex="-1">Builder <a class="header-anchor" href="#builder" aria-label="Permalink to &quot;Builder&quot;">​</a></h1><p>&quot;Builder&quot; in the sidebar is where a modpack is put together as a project, without installing anything. Until the project becomes an instance, neither Minecraft nor the mods are installed: the project keeps the list of mods with pinned versions, resource packs, shaders and configs.</p><p>A finished project can be installed as an instance, exported to <code>.stzhk</code>, or tried with a test run.</p><h2 id="new-project" tabindex="-1">New project <a class="header-anchor" href="#new-project" aria-label="Permalink to &quot;New project&quot;">​</a></h2><ol><li>Sidebar → &quot;Builder&quot; → &quot;Create project&quot;</li><li>Name, Minecraft version and loader</li><li>&quot;Create&quot;</li></ol><p>A Modrinth modpack can become a project too: the &quot;Import .mrpack&quot; button.</p><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to &quot;Contents&quot;">​</a></h2><p>The &quot;Contents&quot; tab is what goes into the modpack, in the sections &quot;Mods&quot;, &quot;Resource packs&quot;, &quot;Shaders&quot;. For each mod:</p><ul><li><strong>Enabled / disabled</strong> — a disabled mod stays in the project, lands disabled in an instance and is left out of the export</li><li><strong>Required / optional</strong> — a mark for whoever installs the modpack</li><li><strong>Side</strong> — &quot;Client&quot;, &quot;Server&quot; or &quot;Both&quot;</li></ul><p>At the top — search within the contents and the total size of the modpack.</p><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><p>The &quot;Catalog&quot; tab searches Modrinth and CurseForge, already narrowed to the project&#39;s Minecraft version and loader. Required dependencies are added together with the mod, and a mod that won&#39;t sit next to those already added is not added — the launcher tells you what it conflicts with.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>The check works without installing — from what mod versions declare on Modrinth and CurseForge, and from the description inside the <code>.jar</code> itself, which lists the versions of other mods it accepts.</p><ul><li><strong>&quot;Problems&quot;</strong> — what is missing (a missing dependency can be added with one button) and what won&#39;t work together. Mods added as a file or without a version can&#39;t be checked — they are listed separately</li><li><strong>&quot;Dependency graph&quot;</strong> — how the project&#39;s mods are linked: what depends on what, what is incompatible with what</li></ul><h2 id="configs" tabindex="-1">Configs <a class="header-anchor" href="#configs" aria-label="Permalink to &quot;Configs&quot;">​</a></h2><p>The &quot;Configs&quot; tab holds the mod settings files that travel with the modpack: into the export and into an instance. Edit them right in the launcher or with &quot;Open in VS Code&quot;; every file keeps a history of changes: you see what changed and can bring back the previous version.</p><h2 id="finished-modpack" tabindex="-1">Finished modpack <a class="header-anchor" href="#finished-modpack" aria-label="Permalink to &quot;Finished modpack&quot;">​</a></h2><ul><li><strong>&quot;Test Run&quot;</strong> — quickly creates an instance <code>[TEST] &lt;name&gt;</code> with the project&#39;s mods and configs, to try the modpack in the game</li><li><strong>Export → &quot;Create instance&quot;</strong> — the same, but under a name of your choice</li><li><strong>Export → &quot;Export to .stzhk&quot;</strong> — the modpack file. With &quot;Embed mods in archive&quot; the file is bigger, but installing it needs no internet; without it, mods are downloaded during the install</li></ul><p>The modpack&#39;s name, version, author and description are in the &quot;Settings&quot; tab.</p><h2 id="build-it-together-with-friends" tabindex="-1">Build it together with friends <a class="header-anchor" href="#build-it-together-with-friends" aria-label="Permalink to &quot;Build it together with friends&quot;">​</a></h2><p>With experimental features on (Settings → General → &quot;Experimental features&quot;), a project gets a &quot;Build together&quot; button: friends see the project in &quot;Friends&quot; and edit it with you, and nobody has to install it. More — <a href="/en/guide/connect.html#coop-build">Co-op build</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><ul><li><a href="/en/guide/modpacks.html">Modpacks</a> — installing, updating and formats</li><li><a href="/en/guide/collections.html">Mod Collections</a> — a set of mods that adapts to any version</li></ul>',24)])])}const m=e(n,[["render",r]]);export{p as __pageData,m as default};
